import _opcode
ops = list(range(-5, 601)) + [-2147483649, -2147483648, 2147483647, 2147483648]
args = [-9223372036854775808, -4294967297, -2147483649, -1, 0, 1, 3, 255, 256, 65535, 2147483646, 2147483647, 2147483648, 4294967295, 4294967296, 9223372036854775807]
for op in ops:
    try:
        print("flags", op, _opcode.is_valid(op), _opcode.has_arg(op), _opcode.has_const(op), _opcode.has_name(op), _opcode.has_jump(op), _opcode.has_free(op), _opcode.has_local(op), _opcode.has_exc(op))
    except OverflowError as e:
        print("overflow", op, str(e))
    for arg in args:
        for jump in range(3):
            try:
                if jump == 2:
                    value = _opcode.stack_effect(op, arg)
                else:
                    value = _opcode.stack_effect(op, arg, jump=jump == 1)
                print("effect", op, arg, jump, value)
            except ValueError as e:
                print("invalid", op, arg, jump, str(e))
            except OverflowError as e:
                print("overflow", op, arg, jump, str(e))

